mapper.select:
SELECT 
FROM love_couple
WHERE deleted = 0

    AND id = #{query.id}


    AND (owner_user_id = #{query.ownerUserId} OR partner_user_id = #{query.ownerUserId})


    AND partner_user_id = #{query.partnerUserId}


    AND status = #{query.status}

ORDER BY update_time DESC, id DESC
LIMIT 1

SELECT 
FROM love_record
WHERE couple_id = #{query.coupleId} AND deleted = 0

    AND creator_user_id = #{query.creatorUserId}


    AND location_id = #{query.locationId}


    AND title LIKE CONCAT('%', #{query.title}, '%')


    AND record_date = #{query.recordDate}


    AND category_code = #{query.categoryCode}


    AND important = #{query.important}

ORDER BY record_date DESC, sort ASC, id DESC

